sys_script_include.script:
var VenueUtils = Class.create();
VenueUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getVenueDetails: function() {
        var venueName = this.getParameter('sysparm_venue_name');
        var gr = new GlideRecord('x_1790116_event_ma_venue');

        gr.addQuery('u_venue_name', venueName);
        gr.query();

        while (gr.next()) {
            return JSON.stringify({
                available: gr.getValue('u_availability') == 'true', 
                location: gr.getValue('u_location'),
                capacity: gr.getValue('u_capacity'),
                contact_person: gr.getValue('u_contact_person'),
                contact_number: gr.getValue('u_contact_number')
            });
        }


    },

    type: 'VenueUtils'
});
